"""Half-open integer interval utilities.

An interval is a pair (start, end) meaning the half-open range [start, end).
A pair with start >= end is empty and is ignored. Inputs may be lists or
tuples of pairs in any order; every function returns a list of
(start, end) tuples sorted by start.
"""

from typing import Iterable, List, Sequence, Tuple

Interval = Tuple[int, int]


def _valid_sorted(intervals: Iterable[Sequence[int]]) -> List[Interval]:
    """Filter out empty/inverted intervals, coerce to tuples, sort by start."""
    pairs = []
    for start, end in intervals:
        if start < end:
            pairs.append((start, end))
    pairs.sort()
    return pairs


def merge(intervals: Iterable[Sequence[int]]) -> List[Interval]:
    """Merge overlapping and touching intervals; O(n log n)."""
    pairs = _valid_sorted(intervals)
    merged: List[Interval] = []
    for start, end in pairs:
        if merged and start <= merged[-1][1]:
            if end > merged[-1][1]:
                merged[-1] = (merged[-1][0], end)
        else:
            merged.append((start, end))
    return merged


def free_gaps(
    intervals: Iterable[Sequence[int]], window: Sequence[int]
) -> List[Interval]:
    """Maximal sub-ranges of [ws, we) not covered by any interval."""
    ws, we = window
    if ws >= we:
        return []
    ws, we = int(ws), int(we)
    clipped = []
    for start, end in intervals:
        if start < end:
            s = max(start, ws)
            e = min(end, we)
            if s < e:
                clipped.append((s, e))
    merged = merge(clipped)
    gaps: List[Interval] = []
    cursor = ws
    for start, end in merged:
        if start > cursor:
            gaps.append((cursor, start))
        if end > cursor:
            cursor = end
    if cursor < we:
        gaps.append((cursor, we))
    return gaps


def max_overlap(intervals: Iterable[Sequence[int]]) -> int:
    """Largest number of non-empty intervals covering one common point."""
    events = []
    for start, end in intervals:
        if start < end:
            events.append((start, 1))
            events.append((end, -1))
    # End events sort before start events at the same point, so touching
    # half-open intervals such as (1, 3) and (3, 5) do not count as overlapping.
    events.sort()
    depth = 0
    best = 0
    for _, delta in events:
        depth += delta
        if depth > best:
            best = depth
    return best

"""LRU cache with per-entry time-to-live (TTL).

See README.md in this directory for the full specification.
"""

import time
from collections import OrderedDict


class TTLCache:
    """A fixed-capacity LRU cache whose entries may carry a TTL."""

    def __init__(self, capacity, clock=time.monotonic):
        if not isinstance(capacity, int) or isinstance(capacity, bool):
            raise ValueError("capacity must be an integer >= 1")
        if capacity < 1:
            raise ValueError("capacity must be >= 1")
        if not callable(clock):
            raise ValueError("clock must be a zero-argument callable")
        self._capacity = capacity
        self._clock = clock
        # Ordered least-recently-used -> most-recently-used.
        # Maps key -> (value, expires) where expires is None (never) or an
        # absolute deadline in seconds returned by the clock.
        self._entries = OrderedDict()

    # ------------------------------------------------------------------ #
    # internal helpers
    # ------------------------------------------------------------------ #
    def _is_expired(self, entry):
        expires = entry[1]
        return expires is not None and self._clock() >= expires

    def _purge_expired(self):
        """Drop every expired entry; return how many were removed."""
        expired = [
            key
            for key, entry in self._entries.items()
            if self._is_expired(entry)
        ]
        for key in expired:
            del self._entries[key]
        return len(expired)

    # ------------------------------------------------------------------ #
    # public API
    # ------------------------------------------------------------------ #
    def put(self, key, value, ttl=None):
        if ttl is not None and ttl <= 0:
            raise ValueError("ttl must be positive")
        expires = None if ttl is None else self._clock() + ttl

        if key in self._entries:
            # Re-storing an existing key refreshes value, lifetime and recency.
            self._entries[key] = (value, expires)
            self._entries.move_to_end(key)
            return

        if len(self._entries) >= self._capacity:
            # Make room for a new key: expired entries go first.
            self._purge_expired()
        if len(self._entries) >= self._capacity:
            # Still full: evict the least recently used entry.
            self._entries.popitem(last=False)
        self._entries[key] = (value, expires)

    def get(self, key, default=None):
        entry = self._entries.get(key)
        if entry is None:
            return default
        if self._is_expired(entry):
            del self._entries[key]
            return default
        self._entries.move_to_end(key)
        return entry[0]

    def __contains__(self, key):
        entry = self._entries.get(key)
        return entry is not None and not self._is_expired(entry)

    def __len__(self):
        self._purge_expired()
        return len(self._entries)

    def keys(self):
        self._purge_expired()
        return list(self._entries)

    def evict_expired(self):
        return self._purge_expired()

"""Arithmetic expression evaluator.

Parses and evaluates an arithmetic expression string using a hand-written
tokenizer plus a recursive-descent parser (no eval/exec/compile/ast).
"""

_FUNCTIONS = ("min", "max", "abs")


def evaluate(text):
    """Parse and evaluate *text*, returning an int or float."""
    tokens = _tokenize(text)
    return _Parser(tokens).parse()


def _tokenize(text):
    if not isinstance(text, str):
        raise ValueError("input must be a string")
    tokens = []
    i = 0
    n = len(text)
    while i < n:
        c = text[i]
        if c.isspace():
            i += 1
            continue
        if c.isdigit() or c == ".":
            j = i
            seen_dot = False
            while j < n and (text[j].isdigit() or (text[j] == "." and not seen_dot)):
                if text[j] == ".":
                    seen_dot = True
                j += 1
            literal = text[i:j]
            if literal == ".":
                raise ValueError("malformed number: %r" % literal)
            value = float(literal) if seen_dot else int(literal)
            tokens.append(("num", value))
            i = j
            continue
        if c.isalpha() or c == "_":
            j = i
            while j < n and (text[j].isalnum() or text[j] == "_"):
                j += 1
            tokens.append(("name", text[i:j]))
            i = j
            continue
        if text.startswith("**", i):
            tokens.append(("op", "**"))
            i += 2
            continue
        if text.startswith("//", i):
            tokens.append(("op", "//"))
            i += 2
            continue
        if c in "+-*/%()":
            tokens.append(("op", c))
            i += 1
            continue
        raise ValueError("unknown character: %r" % c)
    return tokens


class _Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    # -- token helpers ----------------------------------------------------
    def peek(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def at_op(self, *ops):
        tok = self.peek()
        return tok is not None and tok[0] == "op" and tok[1] in ops

    def expect_op(self, op):
        if not self.at_op(op):
            raise ValueError("expected %r, found %s" % (op, _describe(self.peek())))
        self.pos += 1

    # -- grammar ----------------------------------------------------------
    def parse(self):
        if not self.tokens:
            raise ValueError("empty input")
        value = self.expr()
        if self.pos != len(self.tokens):
            raise ValueError("unexpected token: %s" % _describe(self.peek()))
        return value

    def expr(self):
        value = self.term()
        while self.at_op("+", "-"):
            op = self.tokens[self.pos][1]
            self.pos += 1
            rhs = self.term()
            value = value + rhs if op == "+" else value - rhs
        return value

    def term(self):
        value = self.unary()
        while self.at_op("*", "/", "//", "%"):
            op = self.tokens[self.pos][1]
            self.pos += 1
            rhs = self.unary()
            if op == "*":
                value = value * rhs
            elif op == "/":
                value = value / rhs  # always float; ZeroDivisionError propagates
            elif op == "//":
                value = value // rhs
            else:
                value = value % rhs
        return value

    def unary(self):
        if self.at_op("+", "-"):
            op = self.tokens[self.pos][1]
            self.pos += 1
            operand = self.unary()
            return -operand if op == "-" else +operand
        return self.power()

    def power(self):
        base = self.primary()
        if self.at_op("**"):
            self.pos += 1
            exponent = self.unary()  # right-associative; allows 2 ** -3
            return base ** exponent
        return base

    def primary(self):
        tok = self.peek()
        if tok is None:
            raise ValueError("missing operand")
        kind, val = tok
        if kind == "num":
            self.pos += 1
            return val
        if kind == "op" and val == "(":
            self.pos += 1
            value = self.expr()
            self.expect_op(")")
            return value
        if kind == "name":
            self.pos += 1
            return self._call(val)
        raise ValueError("unexpected token: %s" % _describe(tok))

    def _call(self, name):
        if name not in _FUNCTIONS:
            raise ValueError("unknown name: %r" % name)
        self.expect_op("(")
        args = [self.expr()]
        while self.at_op(","):
            self.pos += 1
            args.append(self.expr())
        self.expect_op(")")
        if name == "abs":
            if len(args) != 1:
                raise ValueError("abs() takes exactly one argument (%d given)" % len(args))
            return abs(args[0])
        if not args:
            raise ValueError("%s() expects at least one argument" % name)
        return min(args) if name == "min" else max(args)


def _describe(tok):
    if tok is None:
        return "end of input"
    return "%r" % (tok[1],)
